function close(actual, expected, label) {
  assert.ok(Math.abs(actual-expected) < 1e-7, label + ': ' + actual + ' != ' + expected);
}
function point(actual, expected, label) { for (const axis of ['x','y','z']) close(actual[axis],expected[axis],label+'.'+axis); }
for(const f of fixtures) test('Reference source renderer: '+f.label,()=>{
  const placement=f.front.type==='door'?calculateReferenceDoorPlacement(f.front,f.depth):calculateReferenceDrawerPlacement(f.front,f.depth);
  assert.ok(placement);
  point(placement,f.position,'segment origin');
  const world=p=>({x:p.x+placement.x,y:p.y+placement.y,z:p.z+placement.z});
  if(f.front.type==='door') {
    const front=f.parts[0];
    point(world({x:placement.pivotOffsetX,y:placement.reference.frontOffsetY,z:0}),front,'front center');
    close(placement.width,front.w,'front width');close(placement.height,front.h,'front height');close(placement.reference.thickness,front.d,'front thickness');
    close(placement.reference.openAngle*180/Math.PI,f.open,'open degrees');
    placement.reference.hinges.forEach((h,i)=>point(world(h),f.hinges[i],'hinge'+i));
  } else {
    const parts=getReferenceDrawerParts(f.front,f.depth);
    assert.equal(parts.length,f.parts.length);
    parts.forEach((p,i)=>{assert.equal(p.name,f.parts[i].name);point(p,f.parts[i],p.name);for(const axis of ['w','h','d'])close(p[axis],f.parts[i][axis],p.name+'.'+axis);});
    close(placement.reference.openDistance,f.open,'open travel');
  }
  if(f.handle) point(world(placement.reference.handle),f.handle,'handle');
  else assert.equal(placement.reference.handle,null);
});

test('unsupported drawer heights and shallow depth do not invent box sizes',()=>{
  const front={family:'type02',x:0,y:20,width:40,height:38.2,rowIndex:0,type:'drawer'};
  assert.equal(calculateReferenceDrawerPlacement(front,24),null);
  assert.equal(calculateReferenceDrawerPlacement({...front,height:78.2},32),null);
});
